// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("VotingStatus");

  // Voting Summary state
  const [votingSummary, setVotingSummary] = useState({ totalVoted: 0, students: [] });

  // Reports tab states
  const [reportElection, setReportElection] = useState(null);
  const [reportPosition, setReportPosition] = useState("");
  const [filteredResults, setFilteredResults] = useState({});

  // New Election creation state
  const [newElectionName, setNewElectionName] = useState("");
  const [newElectionStart, setNewElectionStart] = useState("");
  const [newElectionEnd, setNewElectionEnd] = useState("");

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchVotingState = async () => { try { const res = await api.get("/admin/voting-state"); setVotingOpen(res.data.votingOpen); } catch (err) { handleApiError(err); } };
  const fetchPendingUsers = async () => { try { const res = await api.get("/admin/pending-users"); setPendingUsers(res.data); } catch (err) { handleApiError(err); } };
  const fetchCandidates = async () => { try { const res = await api.get("/admin/candidates"); setCandidates(res.data); } catch (err) { handleApiError(err); } };
  const fetchLogs = async () => { try { const res = await api.get("/admin/logs"); setLogs(res.data); } catch (err) { handleApiError(err); } };

  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);
      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        setReportElection(firstElection.id);
        fetchResults(firstElection.id);
      }
    } catch (err) { handleApiError(err); }
  };

  const fetchResults = async (electionId) => {
    try {
      const res = await api.get("/admin/results", { params: { electionId } });
      setResults(res.data.positionResults || {});
      setWinners(res.data.winners || {});
      setFilteredResults(res.data.positionResults || {});
    } catch (err) { handleApiError(err); }
  };

  const fetchVotingSummary = async () => { try { const res = await api.get("/admin/voting-summary"); setVotingSummary(res.data); } catch (err) { handleApiError(err); } };

  const toggleVoting = async () => { try { const res = await api.post("/admin/toggle-voting"); setVotingOpen(res.data.votingOpen); setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`); } catch (err) { handleApiError(err); } };
  const approveUser = async (id) => { try { await api.post(`/admin/approve-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const rejectUser = async (id) => { try { await api.post(`/admin/reject-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const approveCandidate = async (id) => { try { await api.post(`/admin/approve-candidate/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const deleteCandidate = async (id) => { if (!window.confirm("Delete this candidate?")) return; try { await api.delete(`/admin/candidates/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const generateReport = async () => { try { const res = await api.post("/admin/generate-report"); setReportHash(res.data.hash); } catch (err) { handleApiError(err); } };
  const handleElectionChange = (id) => { const election = elections.find((el) => el.id === id); setSelectedElection(id); setSelectedElectionVotingOpen(election?.votingOpen ?? false); setReportElection(id); fetchResults(id); };

  // ---------------- Election Creation ----------------
  const createElection = async () => {
    if (!newElectionName || !newElectionStart || !newElectionEnd) return alert("All fields are required");
    try {
      await api.post("/admin/elections", {
        name: newElectionName,
        startsAt: newElectionStart,
        endsAt: newElectionEnd,
      });
      setNewElectionName(""); setNewElectionStart(""); setNewElectionEnd("");
      fetchElections();
      setMessage("Election created successfully");
    } catch (err) { handleApiError(err); }
  };

  // ---------------- Reports Functions ----------------
  const applyReportFilters = () => {
    let filtered = { ...results };
    if (reportPosition) filtered = { [reportPosition]: filtered[reportPosition] || [] };
    setFilteredResults(filtered);
  };

  const resetReportFilters = () => { setReportElection(selectedElection); setReportPosition(""); setFilteredResults(results); };
  const exportExcel = () => { console.log("Export Excel:", filteredResults); alert("Export Excel functionality triggered"); };
  const exportPDF = () => { console.log("Export PDF:", filteredResults); alert("Export PDF functionality triggered"); };
  const printReport = () => { window.print(); };

  // ---------------- Candidate Actions ----------------
  const rejectCandidateWithComment = async (id) => {
    let comment = "";
    while (!comment) {
      comment = prompt("Enter the rejection reason for the student (required):");
      if (comment === null) return;
      if (!comment.trim()) alert("Comment cannot be empty.");
    }
    if (!window.confirm("Reject this candidate with the entered comment?")) return;
    try { await api.post(`/admin/reject-candidate/${id}`, { comment }); fetchCandidates(); setMessage("Candidate rejected with comment."); } catch (err) { handleApiError(err); }
  };

  // ---------------- Rendered Sections ----------------
  const renderContent = () => {
    switch(activeTab) {
      // ---------------- Voting Status ----------------
      case "VotingStatus": return (
        <>
          <Card title="Create New Election">
            <div style={{ display:"flex", gap:"10px", flexWrap:"wrap" }}>
              <input type="text" placeholder="Election Name" value={newElectionName} onChange={(e)=>setNewElectionName(e.target.value)} style={{ padding:"5px 10px", borderRadius:"6px", flex:"1" }}/>
              <input type="datetime-local" value={newElectionStart} onChange={(e)=>setNewElectionStart(e.target.value)} style={{ padding:"5px 10px", borderRadius:"6px" }}/>
              <input type="datetime-local" value={newElectionEnd} onChange={(e)=>setNewElectionEnd(e.target.value)} style={{ padding:"5px 10px", borderRadius:"6px" }}/>
              <button onClick={createElection} style={{ padding:"8px 15px", borderRadius:"6px", border:"none", background:"#28a745", color:"#fff", cursor:"pointer", fontWeight:"bold" }}>Create Election</button>
            </div>
          </Card>
          <Card title="Voting Status">
            <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>{votingOpen ? "Open" : "Closed"}</p>
            <button onClick={toggleVoting} style={{ marginTop:"10px", padding:"10px 20px", borderRadius:"8px", border:"none", backgroundColor: votingOpen ? "#dc3545" : "#28a745", color:"#fff", cursor:"pointer", fontWeight:"bold" }}>{votingOpen ? "Close Voting" : "Open Voting"}</button>
          </Card>
        </>
      );

      // ---------------- Voting Summary ----------------
      case "VotingSummary": return (
        <Card title="Voting Summary">
          <h3>Total Students Voted: {votingSummary.totalVoted}</h3>
          <table style={{ width:"100%", borderCollapse:"collapse", marginTop:"15px" }}>
            <thead><tr style={{ background:"#f1f1f1" }}><th style={{ padding:"8px", textAlign:"left" }}>Student Number</th><th style={{ padding:"8px", textAlign:"left" }}>Name</th><th style={{ padding:"8px", textAlign:"left" }}>Status</th></tr></thead>
            <tbody>
              {votingSummary.students.length > 0 ? votingSummary.students.map((s,i)=>(<tr key={i} style={{ borderTop:"1px solid #eee" }}><td style={{ padding:"8px" }}>{s.studentNumber}</td><td style={{ padding:"8px" }}>{s.name}</td><td style={{ padding:"8px", fontWeight:"bold", color:"green" }}>{s.status}</td></tr>)) : <tr><td colSpan="3" style={{ padding:"10px", textAlign:"center", color:"#777" }}>No students have voted yet.</td></tr>}
            </tbody>
          </table>
        </Card>
      );

      // ---------------- Pending Users ----------------
      case "PendingUsers": return (
        <Card title="Pending Users">
          {pendingUsers.length === 0 ? <p>No pending users.</p> : (
            <table style={{ width:"100%", borderCollapse:"collapse" }}>
              <thead><tr style={{ background:"#f1f1f1" }}><th>Name</th><th>Email</th><th>Action</th></tr></thead>
              <tbody>
                {pendingUsers.map(u => (
                  <tr key={u.id} style={{ borderTop:"1px solid #eee" }}>
                    <td style={{ padding:"8px" }}>{u.name}</td>
                    <td style={{ padding:"8px" }}>{u.email}</td>
                    <td style={{ padding:"8px", display:"flex", gap:"5px" }}>
                      <button onClick={()=>approveUser(u.id)} style={{ padding:"5px 10px", background:"#28a745", color:"#fff", border:"none", borderRadius:"4px" }}>Approve</button>
                      <button onClick={()=>rejectUser(u.id)} style={{ padding:"5px 10px", background:"#dc3545", color:"#fff", border:"none", borderRadius:"4px" }}>Reject</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </Card>
      );

      // ---------------- Candidates ----------------
      case "Candidates": return (
        <Card title="Candidates">
          {candidates.length === 0 ? <p>No candidates found.</p> : (
            <table style={{ width:"100%", borderCollapse:"collapse" }}>
              <thead><tr style={{ background:"#f1f1f1" }}><th>Name</th><th>Position</th><th>Status</th><th>Actions</th></tr></thead>
              <tbody>
                {candidates.map(c => (
                  <tr key={c.id} style={{ borderTop:"1px solid #eee" }}>
                    <td style={{ padding:"8px" }}>{c.name}</td>
                    <td style={{ padding:"8px" }}>{c.position}</td>
                    <td style={{ padding:"8px", fontWeight:"bold", color:c.status==="approved"?"green":"orange" }}>{c.status}</td>
                    <td style={{ padding:"8px", display:"flex", gap:"5px" }}>
                      {c.status !== "approved" && <button onClick={()=>approveCandidate(c.id)} style={{ padding:"5px 10px", background:"#28a745", color:"#fff", border:"none", borderRadius:"4px" }}>Approve</button>}
                      <button onClick={()=>rejectCandidateWithComment(c.id)} style={{ padding:"5px 10px", background:"#ffc107", color:"#000", border:"none", borderRadius:"4px" }}>Reject</button>
                      <button onClick={()=>deleteCandidate(c.id)} style={{ padding:"5px 10px", background:"#dc3545", color:"#fff", border:"none", borderRadius:"4px" }}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </Card>
      );

      // ---------------- Results ----------------
      case "Results": return (
        <Card title="Election Results">
          {Object.keys(results).length === 0 ? <p>No results available.</p> : (
            <>
              <select value={selectedElection} onChange={(e)=>handleElectionChange(e.target.value)} style={{ marginBottom:"15px", padding:"5px 10px", borderRadius:"6px" }}>
                {elections.map(el=><option key={el.id} value={el.id}>{el.name}</option>)}
              </select>
              {Object.keys(results).map(position=>(
                <div key={position} style={{ marginBottom:"20px" }}>
                  <h4>{position}</h4>
                  <table style={{ width:"100%", borderCollapse:"collapse" }}>
                    <thead><tr style={{ background:"#f1f1f1" }}><th>Candidate</th><th>Votes</th></tr></thead>
                    <tbody>
                      {results[position].map((r,i)=>(<tr key={i}><td style={{ padding:"8px" }}>{r.name}</td><td style={{ padding:"8px" }}>{r.votes}</td></tr>))}
                    </tbody>
                  </table>
                  <p><strong>Winner:</strong> {winners[position]}</p>
                </div>
              ))}
            </>
          )}
        </Card>
      );

      // ---------------- Reports ----------------
      case "Reports": return (
        <Card title="Reports">
          <div style={{ marginBottom:"15px", display:"flex", gap:"10px" }}>
            <select value={reportElection || ""} onChange={(e)=>setReportElection(e.target.value)} style={{ padding:"5px 10px", borderRadius:"6px" }}>
              {elections.map(el=><option key={el.id} value={el.id}>{el.name}</option>)}
            </select>
            <select value={reportPosition} onChange={(e)=>setReportPosition(e.target.value)} style={{ padding:"5px 10px", borderRadius:"6px" }}>
              <option value="">All Positions</option>
              {Object.keys(results).map(pos=><option key={pos} value={pos}>{pos}</option>)}
            </select>
            <button onClick={applyReportFilters} style={{ padding:"5px 10px", borderRadius:"6px", background:"#007bff", color:"#fff", border:"none" }}>Apply</button>
            <button onClick={resetReportFilters} style={{ padding:"5px 10px", borderRadius:"6px", background:"#6c757d", color:"#fff", border:"none" }}>Reset</button>
          </div>

          <div style={{ marginBottom:"15px" }}>
            <button onClick={exportExcel} style={{ marginRight:"5px", padding:"5px 10px", background:"#28a745", color:"#fff", border:"none", borderRadius:"4px" }}>Export Excel</button>
            <button onClick={exportPDF} style={{ marginRight:"5px", padding:"5px 10px", background:"#dc3545", color:"#fff", border:"none", borderRadius:"4px" }}>Export PDF</button>
            <button onClick={printReport} style={{ padding:"5px 10px", background:"#ffc107", color:"#000", border:"none", borderRadius:"4px" }}>Print</button>
          </div>

          {Object.keys(filteredResults).length === 0 ? <p>No data to display.</p> : (
            Object.keys(filteredResults).map(pos=>(
              <div key={pos} style={{ marginBottom:"15px" }}>
                <h4>{pos}</h4>
                <table style={{ width:"100%", borderCollapse:"collapse" }}>
                  <thead><tr style={{ background:"#f1f1f1" }}><th>Candidate</th><th>Votes</th></tr></thead>
                  <tbody>
                    {filteredResults[pos].map((r,i)=>(<tr key={i}><td style={{ padding:"8px" }}>{r.name}</td><td style={{ padding:"8px" }}>{r.votes}</td></tr>))}
                  </tbody>
                </table>
              </div>
            ))
          )}

          <button onClick={generateReport} style={{ marginTop:"15px", padding:"8px 15px", borderRadius:"6px", border:"none", background:"#007bff", color:"#fff" }}>Generate Report</button>
          {reportHash && <p style={{ marginTop:"10px" }}>Report Hash: <strong>{reportHash}</strong></p>}
        </Card>
      );

      default: return null;
    }
  };

  useEffect(() => {
    if (!token) { navigate("/login"); return; }
    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchElections();
      await fetchVotingSummary();
    };
    init();
  }, [token]);

  return (
    <div style={{ display:"flex", minHeight:"100vh", fontFamily:"Arial, sans-serif", backgroundColor:"#f4f6f8" }}>
      {/* Sidebar */}
      <aside style={{
        width: sidebarOpen?"220px":"60px",
        transition:"width 0.3s",
        background:"#343a40",
        color:"#fff",
        paddingTop:"20px",
        display:"flex",
        flexDirection:"column"
      }}>
        <button onClick={()=>setSidebarOpen(!sidebarOpen)} style={{ background:"none", border:"none", color:"#fff", cursor:"pointer", padding:"10px", fontSize:"1.2rem", marginBottom:"20px" }}>☰</button>
        <nav style={{ display:"flex", flexDirection:"column", gap:"10px", paddingLeft: sidebarOpen?"20px":"0" }}>
          <span style={{ cursor:"pointer", fontWeight: activeTab==="VotingSummary"?"bold":"normal" }} onClick={()=>setActiveTab("VotingSummary")}>📋 Voting Summary</span>
          <span style={{ cursor:"pointer", fontWeight: activeTab==="VotingStatus"?"bold":"normal" }} onClick={()=>setActiveTab("VotingStatus")}>🏠 Voting Status</span>
          <span style={{ cursor:"pointer", fontWeight: activeTab==="PendingUsers"?"bold":"normal" }} onClick={()=>setActiveTab("PendingUsers")}>🧑 Pending Users</span>
          <span style={{ cursor:"pointer", fontWeight: activeTab==="Candidates"?"bold":"normal" }} onClick={()=>setActiveTab("Candidates")}>👤 Candidates</span>
          <span style={{ cursor:"pointer", fontWeight: activeTab==="Results"?"bold":"normal" }} onClick={()=>setActiveTab("Results")}>📊 Results</span>
          <span style={{ cursor:"pointer", fontWeight: activeTab==="Reports"?"bold":"normal" }} onClick={()=>setActiveTab("Reports")}>📄 Reports</span>
          <button onClick={()=>{logout();navigate("/login")}} style={{ marginTop:"auto", padding:"10px", borderRadius:"6px", border:"none", background:"#dc3545", color:"#fff", cursor:"pointer", fontWeight:"bold", marginLeft: sidebarOpen?"20px":"0" }}>Logout</button>
        </nav>
      </aside>

      {/* Main Content */}
      <main style={{ flexGrow:1, padding:"30px", maxWidth:"1000px", margin:"0 auto" }}>
        {renderContent()}
        {message && <p style={{ textAlign:"center", color: message.toLowerCase().includes("fail")?"red":"green", fontWeight:"bold", marginTop:"20px" }}>{message}</p>}
      </main>
    </div>
  );
}
